-- EXP05 O01: original ZION Task references through the existing native read protocol.
-- Generated by Supabase CLI; unapplied carrier reconciled above current30010103
-- and active E08/E13 slots30020008/30020013. No applied history is rewritten.
-- Exact original private protocol; references grant no authority. No public API,
-- writer, registry, execution store, provider, approval or budget increase.
BEGIN;
SET LOCAL lock_timeout='2s';
DO $patch$
DECLARE sig text; predecessor text; expected text; old_text text; new_text text;
 p pg_catalog.pg_proc; original_metadata jsonb; definition text; replacement text; n integer; item record;
BEGIN
 FOR sig,predecessor,expected IN SELECT DISTINCT name,before_hash,after_hash FROM (VALUES
 ('public._team_hub_assert_agent_read_scope(public.team_hub_agent_turns)','b5f07681ee7e96548b77e61d71106639','5545c370d54a7baef54ba37f9619e729'),
 ('public.team_hub_stage_agent_read_context(uuid,text,jsonb,jsonb)','472d97fce1007aae021c4902af8701f5','437b5c12b5261b73a38e6a34104c5387'),
 ('public._team_hub_planning_read_annotations(public.team_hub_agent_turns)','3450c2fe42682d9091e3e316ecde0f00','f31a93f9774a628bb1c0c24128fd4674'),
 ('public._team_hub_agent_read_annotations(uuid)','38913fe72f92611a32cb564f68cf836d','7e3bf4f645aec0eb0563b2cfbecc5bb3')
 ) known(name,before_hash,after_hash) LOOP
  SELECT * INTO p FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(sig);
  IF p.oid IS NULL OR p.proowner<>'postgres'::regrole OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
   OR p.pronargdefaults<>0 OR p.proargmodes IS NOT NULL OR p.proacl IS NULL
   OR p.proretset OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u' OR p.prokind<>'f' OR p.provariadic<>0
   OR (p.proname='_team_hub_agent_read_annotations' AND (p.prosecdef OR p.provolatile<>'s'
    OR p.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='sql') OR p.prorettype<>'jsonb'::regtype))
   OR (p.proname<>'_team_hub_agent_read_annotations' AND (NOT p.prosecdef
    OR p.prolang<>(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
    OR p.provolatile<>CASE WHEN p.proname='_team_hub_planning_read_annotations' THEN 's' ELSE 'v' END
    OR p.prorettype<>CASE WHEN p.proname='_team_hub_assert_agent_read_scope' THEN 'void'::regtype ELSE 'jsonb'::regtype END))
   OR (p.proname='team_hub_stage_agent_read_context' AND NOT has_function_privilege('service_role',p.oid,'EXECUTE'))
   OR EXISTS(SELECT 1 FROM pg_catalog.aclexplode(p.proacl) a WHERE a.is_grantable OR a.privilege_type<>'EXECUTE'
    OR (a.grantee<>p.proowner AND (p.proname<>'team_hub_stage_agent_read_context' OR a.grantee<>'service_role'::regrole)))
   OR md5(p.prosrc) NOT IN (predecessor,expected) THEN RAISE EXCEPTION 'Original O01 protocol drift: %',sig; END IF;
  original_metadata:=to_jsonb(p)-'prosrc'; replacement:=p.prosrc;
  IF md5(replacement)=predecessor THEN
   FOR item IN SELECT * FROM (VALUES
 ('public._team_hub_assert_agent_read_scope(public.team_hub_agent_turns)',0,'b5f07681ee7e96548b77e61d71106639','5545c370d54a7baef54ba37f9619e729',$old$  IF t.consumed_at IS NULL AND (t.read_context->>'expires_at')::timestamptz<=clock_timestamp() THEN$old$,$new$  IF t.agent_key='zion' THEN
   FOR item IN SELECT value FROM jsonb_array_elements(coalesce(t.read_context->'record_links','[]'::jsonb)) LOOP
    IF item->>'destination'='operations_work' AND jsonb_typeof(item->'record_id')='string' AND NOT (item ? 'record_kind') THEN
     IF NOT (tools ? 'crm_list_tasks' OR tools ? 'crm_get_task') THEN
      RAISE EXCEPTION 'Original Task read required' USING ERRCODE='42501'; END IF;
     PERFORM 1 FROM public.tasks r WHERE r.id=(item->>'record_id')::uuid AND r.tenant_id=t.tenant_id FOR SHARE;
     IF NOT FOUND THEN RAISE EXCEPTION 'Original Task reference unavailable' USING ERRCODE='42501'; END IF;
    END IF;
   END LOOP;
  END IF;
  IF t.consumed_at IS NULL AND (t.read_context->>'expires_at')::timestamptz<=clock_timestamp() THEN$new$),
 ('public.team_hub_stage_agent_read_context(uuid,text,jsonb,jsonb)',0,'472d97fce1007aae021c4902af8701f5','437b5c12b5261b73a38e6a34104c5387',$old$   WHERE value->>'record_kind'='planning_item' OR value->>'destination'='calendar';$old$,$new$   WHERE value->>'record_kind'='planning_item' OR value->>'destination'='calendar'
    OR (t.agent_key='zion' AND value->>'destination'='operations_work' AND jsonb_typeof(value->'record_id')='string' AND NOT (value ? 'record_kind'));$new$),
 ('public.team_hub_stage_agent_read_context(uuid,text,jsonb,jsonb)',1,'472d97fce1007aae021c4902af8701f5','437b5c12b5261b73a38e6a34104c5387',$old$    WHEN 'operations_work' THEN link->>'record_kind'='planning_item' AND planning IS NOT NULL
     AND planning->'items' @> jsonb_build_array(ref)$old$,$new$    WHEN 'operations_work' THEN CASE WHEN link->>'record_kind'='planning_item' THEN planning IS NOT NULL
     AND planning->'items' @> jsonb_build_array(ref)
     ELSE t.agent_key='zion' AND (tools ? 'crm_list_tasks' OR tools ? 'crm_get_task')
      AND EXISTS(SELECT 1 FROM public.tasks r WHERE r.id=ref AND r.tenant_id=t.tenant_id) END$new$),
 ('public.team_hub_stage_agent_read_context(uuid,text,jsonb,jsonb)',2,'472d97fce1007aae021c4902af8701f5','437b5c12b5261b73a38e6a34104c5387',$old$ IF planning IS NOT NULL OR calendar IS NOT NULL THEN
  SELECT jsonb_agg(DISTINCT tool ORDER BY tool) INTO tools$old$,$new$ IF planning IS NOT NULL OR calendar IS NOT NULL OR (t.agent_key='zion' AND (
  p_read_tools ? 'crm_list_tasks' OR p_read_tools ? 'crm_get_task' OR (t.read_context->>'token_hash'=t.token_hash
   AND ((t.read_context->'tools') ? 'crm_list_tasks' OR (t.read_context->'tools') ? 'crm_get_task')))) THEN
  SELECT jsonb_agg(DISTINCT tool ORDER BY tool) INTO tools$new$),
 ('public.team_hub_stage_agent_read_context(uuid,text,jsonb,jsonb)',3,'472d97fce1007aae021c4902af8701f5','437b5c12b5261b73a38e6a34104c5387',$old$ IF planning IS NOT NULL OR calendar IS NOT NULL THEN
  SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO links$old$,$new$ IF planning IS NOT NULL OR calendar IS NOT NULL OR (t.agent_key='zion'
  AND (tools ? 'crm_list_tasks' OR tools ? 'crm_get_task')) THEN
  SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO links$new$),
 ('public._team_hub_planning_read_annotations(public.team_hub_agent_turns)',0,'3450c2fe42682d9091e3e316ecde0f00','f31a93f9774a628bb1c0c24128fd4674',$old$md5(p.prosrc)='b5f07681ee7e96548b77e61d71106639'$old$,$new$md5(p.prosrc)='5545c370d54a7baef54ba37f9619e729'$new$),
 ('public._team_hub_planning_read_annotations(public.team_hub_agent_turns)',1,'3450c2fe42682d9091e3e316ecde0f00','f31a93f9774a628bb1c0c24128fd4674',$old$ RETURN '{}'::jsonb;$old$,$new$ FOR item IN SELECT value FROM jsonb_array_elements(coalesce(t.read_context->'record_links','[]'::jsonb)) LOOP
  IF item->>'destination'='operations_work' AND jsonb_typeof(item->'record_id')='string' AND NOT (item ? 'record_kind') THEN
   IF NOT (tools ? 'crm_list_tasks' OR tools ? 'crm_get_task')
    OR NOT EXISTS(SELECT 1 FROM public.tasks r WHERE r.id=(item->>'record_id')::uuid AND r.tenant_id=t.tenant_id) THEN
    RAISE EXCEPTION 'Original Task history unavailable' USING ERRCODE='42501'; END IF;
  END IF;
 END LOOP;
 RETURN '{}'::jsonb;$new$),
 ('public._team_hub_agent_read_annotations(uuid)',0,'38913fe72f92611a32cb564f68cf836d','7e3bf4f645aec0eb0563b2cfbecc5bb3',$old$CASE WHEN t.read_context ? 'planning' OR t.read_context ? 'calendar' THEN$old$,$new$CASE WHEN t.read_context ? 'planning' OR t.read_context ? 'calendar'
    OR (t.agent_key='zion' AND ((t.read_context->'tools') ? 'crm_list_tasks' OR (t.read_context->'tools') ? 'crm_get_task')) THEN$new$)
   ) h(name,ordinal,before_hash,after_hash,old_text,new_text) WHERE name=sig ORDER BY ordinal LOOP
    IF (length(replacement)-length(replace(replacement,item.old_text,'')))/length(item.old_text)<>1 THEN
     RAISE EXCEPTION 'Original O01 hunk drift: %',sig; END IF;
    replacement:=replace(replacement,item.old_text,item.new_text);
   END LOOP;
   IF md5(replacement)<>expected THEN RAISE EXCEPTION 'Original O01 whole-source mismatch: %',sig; END IF;
   definition:=pg_catalog.pg_get_functiondef(p.oid); n:=strpos(definition,'AS $function$');
   IF n=0 THEN RAISE EXCEPTION 'Original O01 delimiter drift: %',sig; END IF;
   EXECUTE left(definition,n-1)||'AS $function$'||replacement||'$function$';
  END IF;
  IF (SELECT to_jsonb(q)-'prosrc' FROM pg_catalog.pg_proc q WHERE q.oid=p.oid) IS DISTINCT FROM original_metadata THEN
   RAISE EXCEPTION 'Original O01 complete ABI/ACL/config changed: %',sig; END IF;
 END LOOP;
END $patch$;
COMMIT;
